import pandas as pd, numpy as np
df = pd.read_csv('bn_sample_10k.csv')
names = list(df.columns)
data = df.values
n = data.shape[0]
idx = {nm:i for i,nm in enumerate(names)}
parents = {'U': [], 'Y': ['U'], 'R': ['U'], 'D': ['U','Y'], 'M': ['U','R']}
cpds = {}
for ch in names:
    ci = idx[ch]; Xc = data[:, ci]; pn = parents[ch]
    if not pn:
        beta = np.array([Xc.mean()])
    else:
        A = np.column_stack([np.ones(n)] + [data[:, idx[a]] for a in pn])
        beta, *_ = np.linalg.lstsq(A, Xc, rcond=None)
    resid = Xc - (np.ones(n) if not pn else np.column_stack([np.ones(n)] + [data[:, idx[a]] for a in pn])) @ beta
    cpds[ch] = (beta, resid.std(ddof=1), pn)

rng = np.random.default_rng(123)
def sample(m, do_Y=None):
    out = {}
    for ch in ['U','Y','R','D','M']:
        beta, sigma, pn = cpds[ch]
        val = beta[0] + sum(beta[k+1]*out[a] for k,a in enumerate(pn))
        if do_Y is not None and ch == 'Y':
            out[ch] = 0.0 + rng.normal(0, 1e-9)
            continue
        out[ch] = val + rng.normal(0, sigma)
    return np.column_stack([out[nm] for nm in names])

s0 = sample(10000)
print("No-intervention resample check:")
for i,nm in enumerate(names):
    print(f"  {nm}: mean {s0[:,i].mean():.3f} (orig {data[:,i].mean():.3f}), std {s0[:,i].std():.3f} (orig {data[:,i].std():.3f})")
for a,b in [('U','M'),('R','M'),('Y','D'),('R','D'),('U','Y')]:
    co = np.corrcoef(data[:,idx[a]], data[:,idx[b]])[0,1]
    cr = np.corrcoef(s0[:,idx[a]], s0[:,idx[b]])[0,1]
    print(f"  corr({a},{b}): orig {co:.4f} resamp {cr:.4f}")

# Intervention do(Y=0)
s1 = sample(10000, do_Y=True)
print("\nIntervention do(Y=0) resample:")
for i,nm in enumerate(names):
    print(f"  {nm}: mean {s1[:,i].mean():.3f} (orig {data[:,i].mean():.3f}), std {s1[:,i].std():.3f} (orig {data[:,i].std():.3f})")
print("Y range:", s1[:,1].min(), s1[:,1].max())
for a,b in [('U','D'),('U','M'),('U','R'),('Y','D'),('R','D')]:
    cr = np.corrcoef(s1[:,idx[a]], s1[:,idx[b]])[0,1]
    print(f"  corr({a},{b}) after intervention: {cr:.4f}")

pd.DataFrame(s1, columns=names).to_csv('/tmp/check_interv.csv', index=False)
print("saved /tmp/check_interv.csv")
